// Collect system metrics from Netdata HTTP API
// Makes parallel HTTP GET requests to all Netdata endpoints
// Outputs consolidated metrics object for health-aggregator
// Per-cycle state isolated via closure to prevent race conditions (M3)

var requests = [
    {name: 'cpu', path: '/api/v1/data?chart=system.cpu&after=-1&points=1&format=json'},
    {name: 'ram', path: '/api/v1/data?chart=system.ram&after=-1&points=1&format=json'},
    {name: 'disk', path: '/api/v1/data?chart=disk_space./&after=-1&points=1&format=json'},
    {name: 'uptime', path: '/api/v1/data?chart=system.uptime&after=-1&points=1&format=json'}
];

var STALENESS_CUTOFF_MS = 5 * 60 * 1000; // 5 minutes (L2)

// Isolate per-cycle state in closure to prevent race condition (M3)
(function(cycleMsg) {
    var metrics = {};
    var completed = 0;
    var total = requests.length;

    function makeRequest(req) {
        var options = {
            hostname: 'netdata',
            port: 19999,
            path: req.path,
            method: 'GET',
            timeout: 5000
        };

        try {
            var httpReq = http.get(options, function(res) {
                var body = '';
                res.on('data', function(chunk) { body += chunk; });
                res.on('end', function() {
                    try {
                        var data = JSON.parse(body);
                        if (data && data.data && data.data.length > 0) {
                            metrics[req.name] = {labels: data.labels || [], values: data.data[0]};
                        } else {
                            metrics[req.name] = null;
                        }
                    } catch (e) {
                        metrics[req.name] = null;
                        node.error('[gateway-health] NetdataParseError: failed to parse ' + req.name + ' response', cycleMsg);
                    }
                    checkComplete();
                });
            });

            httpReq.on('error', function(e) {
                try {
                    metrics[req.name] = null;
                    node.error('[gateway-health] NetdataRequestError: ' + req.name + ' - ' + e.message, cycleMsg);
                } catch (err) {
                    node.error('[gateway-health] CallbackError: ' + err.message, cycleMsg);
                }
                checkComplete();
            });

            httpReq.on('timeout', function() {
                try {
                    httpReq.destroy();
                    metrics[req.name] = null;
                    node.error('[gateway-health] NetdataTimeout: ' + req.name + ' request timed out', cycleMsg);
                } catch (err) {
                    node.error('[gateway-health] CallbackError: ' + err.message, cycleMsg);
                }
                checkComplete();
            });
        } catch (e) {
            metrics[req.name] = null;
            node.error('[gateway-health] RequestSetupError: ' + req.name + ' - ' + e.message, cycleMsg);
            checkComplete();
        }
    }

    function checkComplete() {
        completed++;
        if (completed >= total) {
            // Store last known metrics with timestamps for staleness detection (L2)
            var lastMetrics = flow.get('lastNetdataMetrics') || {};
            var now = Date.now();
            for (var key in metrics) {
                if (metrics[key] !== null) {
                    lastMetrics[key] = {data: metrics[key], ts: now};
                } else if (lastMetrics[key] && lastMetrics[key].data) {
                    // Staleness cutoff: revert to null if cached > 5 min (L2)
                    if (now - (lastMetrics[key].ts || 0) > STALENESS_CUTOFF_MS) {
                        metrics[key] = null;
                    } else {
                        metrics[key] = lastMetrics[key].data;
                    }
                }
            }
            flow.set('lastNetdataMetrics', lastMetrics);

            cycleMsg.metrics = metrics;
            node.send(cycleMsg);
            node.done();
        }
    }

    for (var i = 0; i < requests.length; i++) {
        makeRequest(requests[i]);
    }
})(msg);

return null;

// Aggregate Netdata metrics + flow context into ThingsBoard health payload
// Output 1: cloud telemetry (v1/devices/me/telemetry)
// Output 2: local health status (nexus/internal/gateway-health-status)

var m = msg.metrics || {};

// Clamp helper: ensure percentage values stay in [0, 100] range (M4)
function clampPct(val) {
    if (val < 0) return -1; // preserve -1 sentinel for unknown
    return parseFloat(Math.min(100, Math.max(0, val)).toFixed(2));
}

// --- CPU usage ---
// Strategy 1: 100 - idle (when idle label present)
// Strategy 2: sum all non-time values (when Netdata omits idle)
var cpu_usage_pct = -1;
if (m.cpu && m.cpu.labels && m.cpu.values) {
    var idleIdx = m.cpu.labels.indexOf('idle');
    if (idleIdx >= 0) {
        cpu_usage_pct = clampPct(100 - m.cpu.values[idleIdx]);
    } else {
        // No idle label — sum all active CPU components (skip index 0 = time)
        var cpuSum = 0;
        for (var ci = 1; ci < m.cpu.values.length; ci++) {
            cpuSum += m.cpu.values[ci];
        }
        cpu_usage_pct = clampPct(cpuSum);
    }
}

// --- RAM usage: used / (used + free + cached + buffers) * 100 ---
var ram_usage_pct = -1;
if (m.ram && m.ram.labels && m.ram.values) {
    var ramLabels = m.ram.labels;
    var ramValues = m.ram.values;
    var usedIdx = ramLabels.indexOf('used');
    var freeIdx = ramLabels.indexOf('free');
    var cachedIdx = ramLabels.indexOf('cached');
    var buffersIdx = ramLabels.indexOf('buffers');
    if (usedIdx >= 0 && freeIdx >= 0) {
        var used = ramValues[usedIdx];
        var free = ramValues[freeIdx];
        var cached = cachedIdx >= 0 ? ramValues[cachedIdx] : 0;
        var buffersMem = buffersIdx >= 0 ? ramValues[buffersIdx] : 0;
        var total = used + free + cached + buffersMem;
        if (total > 0) {
            ram_usage_pct = clampPct((used / total) * 100);
        }
    }
}

// --- Disk usage: used / (used + avail) * 100 ---
var disk_usage_pct = -1;
if (m.disk && m.disk.labels && m.disk.values) {
    var diskLabels = m.disk.labels;
    var diskValues = m.disk.values;
    var dUsedIdx = diskLabels.indexOf('used');
    var dAvailIdx = diskLabels.indexOf('avail');
    if (dUsedIdx >= 0 && dAvailIdx >= 0) {
        var dUsed = diskValues[dUsedIdx];
        var dAvail = diskValues[dAvailIdx];
        if (dUsed + dAvail > 0) {
            disk_usage_pct = clampPct((dUsed / (dUsed + dAvail)) * 100);
        }
    }
}

// --- Uptime ---
var uptime_seconds = 0;
if (m.uptime && m.uptime.values && m.uptime.values.length > 1) {
    uptime_seconds = Math.round(m.uptime.values[1]);
}

// --- Flow context values ---
var cloud_connected = flow.get('cloudConnected');
if (typeof cloud_connected !== 'boolean') {
    cloud_connected = false;
}
var buffer_queue_size = flow.get('bufferQueueSize') || 0;
var buffering_active = flow.get('bufferingActive');
if (typeof buffering_active !== 'boolean') {
    buffering_active = false;
}
var iec104_connected = flow.get('iec104Connected');
if (typeof iec104_connected !== 'boolean') {
    iec104_connected = false;
}
var rbe_filtered_count = global.get('rbeFilteredCount') || 0;

// --- Build ThingsBoard native flat JSON payload ---
var healthPayload = {
    ts: Date.now(),
    values: {
        cpu_usage_pct: cpu_usage_pct,
        ram_usage_pct: ram_usage_pct,
        disk_usage_pct: disk_usage_pct,
        uptime_seconds: uptime_seconds,
        mqtt_connected: true,
        cloud_connected: cloud_connected,
        buffer_queue_size: buffer_queue_size,
        buffering_active: buffering_active,
        iec104_connected: iec104_connected,
        rbe_filtered_count: rbe_filtered_count
    }
};

var cloudMsg = {payload: healthPayload, topic: 'v1/devices/me/telemetry'};
var localMsg = {payload: healthPayload, topic: 'nexus/internal/gateway-health-status'};

node.status({fill: cloud_connected ? 'green' : 'yellow', shape: 'dot', text: 'cpu:' + cpu_usage_pct + '% ram:' + ram_usage_pct + '% disk:' + disk_usage_pct + '%'});

return [cloudMsg, localMsg];

