// Initialize default flow context values on deploy/restart
flow.set('cloudConnected', false);
flow.set('bufferQueueSize', 0);
flow.set('bufferingActive', false);
flow.set('lastNetdataMetrics', {});
flow.set('iec104Connected', false);
global.set('rbeFilteredCount', 0);
node.status({fill: 'grey', shape: 'ring', text: 'initializing'});

