// Parse cloud connection status and store in flow context
// Input: {cloud_connected: true/false, ts: <epoch_ms>}

var data;
try {
    data = (typeof msg.payload === 'string') ? JSON.parse(msg.payload) : msg.payload;
} catch (e) {
    node.error('[gateway-health] ParseError: invalid cloud-connection-status payload', msg);
    return null;
}

if (typeof data.cloud_connected === 'boolean') {
    flow.set('cloudConnected', data.cloud_connected);
    if (data.cloud_connected) {
        node.status({fill: 'green', shape: 'dot', text: 'cloud connected'});
    } else {
        node.status({fill: 'red', shape: 'ring', text: 'cloud disconnected'});
    }
}

return null;

// Parse buffer status and store in flow context
// Input: {buffering_active: boolean, buffer_queue_size: <count>, ts: <epoch_ms>}

var data;
try {
    data = (typeof msg.payload === 'string') ? JSON.parse(msg.payload) : msg.payload;
} catch (e) {
    node.error('[gateway-health] ParseError: invalid buffer-status payload', msg);
    return null;
}

if (typeof data.buffer_queue_size === 'number') {
    flow.set('bufferQueueSize', data.buffer_queue_size);
}
if (typeof data.buffering_active === 'boolean') {
    flow.set('bufferingActive', data.buffering_active);
}

var qSize = flow.get('bufferQueueSize') || 0;
var active = flow.get('bufferingActive') || false;
node.status({fill: active ? 'yellow' : 'green', shape: active ? 'ring' : 'dot', text: 'buffer: ' + qSize});

return null;

// Format error message for logging and publishing
var errorSource = msg.error ? msg.error.source : {};
var errorMsg = msg.error ? msg.error.message : 'Unknown error';
var nodeName = errorSource.name || errorSource.id || 'unknown';

// Derive error_type from message pattern [gateway-health] Type: or from node name
var errorType = 'UnknownError';
var typeMatch = errorMsg.match(/\[gateway-health\]\s+(\w+):\s*(.*)/);
if (typeMatch) {
    errorType = typeMatch[1];
    errorMsg = typeMatch[2];
} else {
    errorType = nodeName.replace(/[^a-zA-Z0-9]/g, '_') + '_Error';
}

node.warn('[gateway-health] ' + errorType + ': ' + errorMsg);

msg.payload = JSON.stringify({
    error_type: errorType,
    source: nodeName,
    message: errorMsg.substring(0, 200),
    ts: Date.now()
});
msg.topic = 'nexus/internal/gateway-health-errors';

return msg;

// Parse IEC104 connection status and store in flow context
// Input: {iec104_connected: true/false, ts: <epoch_ms>}

var data;
try {
    data = (typeof msg.payload === 'string') ? JSON.parse(msg.payload) : msg.payload;
} catch (e) {
    node.error('[gateway-health] ParseError: invalid iec104-status payload', msg);
    return null;
}

if (typeof data.iec104_connected === 'boolean') {
    flow.set('iec104Connected', data.iec104_connected);
    if (data.iec104_connected) {
        node.status({fill: 'green', shape: 'dot', text: 'IEC104 connected'});
    } else {
        node.status({fill: 'grey', shape: 'ring', text: 'IEC104 disconnected'});
    }
}

return null;

// Parse RBE filter status and store filtered count in flow context
// Input: {filtered_count: <number>, timestamp: <epoch_ms>}

var data;
try {
    data = (typeof msg.payload === 'string') ? JSON.parse(msg.payload) : msg.payload;
} catch (e) {
    node.error('[gateway-health] ParseError: invalid rbe-status payload', msg);
    return null;
}

if (typeof data.filtered_count === 'number') {
    global.set('rbeFilteredCount', data.filtered_count);
    node.status({fill: 'blue', shape: 'dot', text: 'RBE filtered: ' + data.filtered_count});
}

return null;
